/** Suggested monthly subscription prices (cents). */
export const AFFILIATE_TIER_PRICES_CENTS: Record<AffiliatePlan, number> = {
  standard: 20_000, // $200
  master: 50_000, // $500
  sub_affiliate: 0,
};

