function parseNotifyExtraEvents(raw: unknown): AdminNotifyEventKey[] | null {
  if (raw == null || raw === "") return null;
  let parsed: unknown = raw;
  if (typeof raw === "string") {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!Array.isArray(parsed)) return null;
  const allowed = new Set<string>(ADMIN_NOTIFY_EVENT_KEYS);
  return parsed
    .map((x) => String(x))
    .filter((k): k is AdminNotifyEventKey => allowed.has(k));
}

/** undefined = omit from update; null = all events; [] = none; else selected keys. */
function normalizeNotifyExtraEventsInput(
  raw: unknown,
): AdminNotifyEventKey[] | null | undefined {
  if (raw === undefined) return undefined;
  if (raw === null) return null;
  if (!Array.isArray(raw)) return undefined;
  return parseNotifyExtraEvents(raw) ?? [];
}

function mapNotifyExtraEmailRow(r: RowDataPacket) {
  return {
    id: Number(r.id),
    email: String(r.email),
    label: r.label ? String(r.label) : null,
    is_active: !!r.is_active,
    events: parseNotifyExtraEvents(r.events_json),
    created_at: r.created_at,
    updated_at: r.updated_at,
  };
}

function notifyExtraAllowsEvent(
  events: AdminNotifyEventKey[] | null,
  eventKey: AdminNotifyEventKey,
): boolean {
  if (events == null) return true;
  return events.includes(eventKey);
}

async function listActiveNotifyExtraEmails(): Promise<
  {
    id: number;
    email: string;
    label: string | null;
    events: AdminNotifyEventKey[] | null;
  }[]
> {
  try {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, email, label, events_json FROM admin_notify_extra_emails
       WHERE is_active = 1
       ORDER BY id ASC`,
    );
    const out: {
      id: number;
      email: string;
      label: string | null;
      events: AdminNotifyEventKey[] | null;
    }[] = [];
    for (const r of rows) {
      const email = String(r.email || "").trim().toLowerCase();
      if (!email || !isValidEmail(email)) continue;
      out.push({
        id: Number(r.id),
        email,
        label: r.label ? String(r.label) : null,
        events: parseNotifyExtraEvents(r.events_json),
      });
    }
    return out;
  } catch (e: any) {
    console.warn(
      "[notify:extra_emails] list failed (table missing?):",
      e?.message ?? e,
    );
    return [];
  }
}

/** Email-only fan-out to Settings → Notifications list (skips already-sent addresses). */
async function emailAdminNotifyExtraRecipients(opts: {
  subject: string;
  html: string;
  eventKey: AdminNotifyEventKey;
  skipEmails?: Set<string>;
}): Promise<number> {
  const extras = await listActiveNotifyExtraEmails();
  if (!extras.length) return 0;
  const skip = opts.skipEmails || new Set<string>();
  let sent = 0;
  await Promise.all(
    extras.map(async (row) => {
      if (skip.has(row.email)) return;
      if (!notifyExtraAllowsEvent(row.events, opts.eventKey)) return;
      try {
        await sendEmail({
          to: row.email,
          subject: opts.subject,
          html: opts.html,
        });
        sent += 1;
        skip.add(row.email);
      } catch (e: any) {
        console.error(
          `[notify:extra_email] ${row.email}:`,
          e?.message ?? e,
        );
      }
    }),
  );
  return sent;
}

type TeamAdminRecipient = {
  id: number;
  email: string;
  first_name: string;
  phone: string | null;
  preferred_language: string | null;
  prefs: AdminNotificationPrefs;
};

/** Active Optimum staff (excludes affiliate portal users). */
async function listActiveTeamAdmins(): Promise<TeamAdminRecipient[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, phone, preferred_language, notification_prefs_json
     FROM admins
     WHERE status = 'active'
       AND role IN ('super_admin', 'admin', 'agent')
       AND email IS NOT NULL AND TRIM(email) <> ''`,
  );
  return rows.map((r) => ({
    id: Number(r.id),
    email: String(r.email),
    first_name: String(r.first_name || "Admin"),
    phone: r.phone ? String(r.phone) : null,
    preferred_language: (r.preferred_language as string) || "en",
    prefs: parseAdminNotificationPrefs(r.notification_prefs_json),
  }));
}

type TeamAdminNotifyBuild = {
  subject: string;
  html: string;
  inAppTitle: string;
  inAppBody: string;
  linkUrl: string;
  smsBody?: string;
};

async function deliverAdminNotificationChannels(opts: {
  admin: TeamAdminRecipient;
  eventKey: AdminNotifyEventKey;
  tpl: TeamAdminNotifyBuild;
}): Promise<{ email: boolean; in_app: boolean; sms: boolean }> {
  const { admin, eventKey, tpl } = opts;
  const result = { email: false, in_app: false, sms: false };

  if (adminNotifyPrefOn(admin.prefs, "email", eventKey)) {
    try {
      await sendEmail({
        to: admin.email,
        subject: tpl.subject,
        html: tpl.html,
      });
      result.email = true;
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:email] ${admin.email}:`,
        e?.message ?? e,
      );
    }
  }

  if (adminNotifyPrefOn(admin.prefs, "in_app", eventKey)) {
    try {
      const notifId = await insertAdminInAppNotification({
        adminId: admin.id,
        eventKey,
        title: tpl.inAppTitle,
        body: tpl.inAppBody,
        linkUrl: tpl.linkUrl,
      });
      result.in_app = true;
      if (notifId) {
        await publishAdminBellRealtime(admin.id, {
          notification_id: notifId,
          event_key: eventKey,
        });
      }
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:in_app] admin ${admin.id}:`,
        e?.message ?? e,
      );
    }
  }

  if (
    adminNotifyPrefOn(admin.prefs, "sms", eventKey) &&
    admin.phone
  ) {
    try {
      const from = await resolveAssignedSmsFrom(admin.id);
      if (!from) {
        // No OFG number → SMS notifications stay off for this staff member
      } else {
        const smsText =
          tpl.smsBody ||
          `${tpl.inAppTitle}: ${tpl.inAppBody}`.slice(0, 320);
        await sendSms({ to: admin.phone, body: smsText, from });
        result.sms = true;
      }
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:sms] ${admin.phone}:`,
        e?.message ?? e,
      );
    }
  }

  return result;
}

async function notifyAllTeamAdmins(
  eventKey: AdminNotifyEventKey,
  build: (admin: TeamAdminRecipient) => TeamAdminNotifyBuild,
): Promise<{ sent: number; errors: string[] }> {
  const admins = await listActiveTeamAdmins();
  if (admins.length === 0) {
    console.warn(
      "[notifyAllTeamAdmins] no active team admins with email — alert skipped",
    );
    return { sent: 0, errors: ["no_active_team_admins"] };
  }
  const errors: string[] = [];
  let sent = 0;
  const emailedAdmins = new Set<string>();
  let sampleEmailTpl: { subject: string; html: string } | null = null;
  await Promise.all(
    admins.map(async (admin) => {
      try {
        const tpl = build(admin);
        if (!sampleEmailTpl) {
          sampleEmailTpl = { subject: tpl.subject, html: tpl.html };
        }
        const delivered = await deliverAdminNotificationChannels({
          admin,
          eventKey,
          tpl,
        });
        if (delivered.email) {
          emailedAdmins.add(admin.email.trim().toLowerCase());
        }
        if (delivered.email || delivered.in_app || delivered.sms) sent += 1;
      } catch (e: any) {
        errors.push(`${admin.email}: ${e?.message ?? e}`);
      }
    }),
  );
  if (sampleEmailTpl) {
    const extraSent = await emailAdminNotifyExtraRecipients({
      subject: sampleEmailTpl.subject,
      html: sampleEmailTpl.html,
      eventKey,
      skipEmails: emailedAdmins,
    });
    sent += extraSent;
  }
  if (errors.length) {
    console.error("[notifyAllTeamAdmins] partial failures:", errors.join("; "));
  }
  return { sent, errors };
}

/**
 * Email the language-owner admin when a client is sent a document upload link.
 */
async function notifyLanguageOwnerDocUploadLink(opts: {
  clientId: number;
  firstName: string;
  lastName: string;
  clientEmail: string;
  lang: string;
  portalUrl: string;
  assignedAdminId?: number | null;
  caseId?: number | null;
}): Promise<void> {
  let ownerId = opts.assignedAdminId ?? null;
  if (!ownerId) {
    const [cRows] = await pool.query<RowDataPacket[]>(
      `SELECT assigned_admin_id, preferred_language FROM clients WHERE id = ? LIMIT 1`,
      [opts.clientId],
    );
    ownerId = cRows[0]?.assigned_admin_id
      ? Number(cRows[0].assigned_admin_id)
      : await resolveLanguageOwnerAdminId(
          cRows[0]?.preferred_language === "es" ? "es" : "en",
        );
  }
  if (!ownerId) return;
  const [aRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, phone, preferred_language, status, notification_prefs_json
     FROM admins WHERE id = ? LIMIT 1`,
    [ownerId],
  );
  const adminRow = aRows[0];
  if (!adminRow || adminRow.status !== "active" || !adminRow.email) return;
  const admin: TeamAdminRecipient = {
    id: Number(adminRow.id),
    email: String(adminRow.email),
    first_name: String(adminRow.first_name || "Admin"),
    phone: adminRow.phone ? String(adminRow.phone) : null,
    preferred_language: (adminRow.preferred_language as string) || "en",
    prefs: parseAdminNotificationPrefs(adminRow.notification_prefs_json),
  };
  const adminLang = admin.preferred_language === "es" ? "es" : "en";
  const caseUploadUrl = opts.caseId
    ? `${APP_URL}/admin/pipeline?case=${opts.caseId}`
    : `${APP_URL}/admin/clients`;
  const tplEmail = tplAdminDocUploadLinkAlert({
    adminFirstName: admin.first_name,
    clientName: `${opts.firstName} ${opts.lastName}`.trim(),
    clientEmail: opts.clientEmail,
    portalUrl: opts.portalUrl,
    caseUploadUrl,
    lang: adminLang,
  });
  const clientName = `${opts.firstName} ${opts.lastName}`.trim();
  await deliverAdminNotificationChannels({
    admin,
    eventKey: "doc_upload_link",
    tpl: {
      subject: tplEmail.subject,
      html: tplEmail.html,
      inAppTitle:
        adminLang === "es"
          ? "Enlace de carga enviado"
          : "Upload link sent",
      inAppBody:
        adminLang === "es"
          ? `Se envió el enlace del portal a ${clientName}.`
          : `Portal upload link sent to ${clientName}.`,
      linkUrl: caseUploadUrl,
      smsBody: `Optimum: upload link sent to ${clientName}`,
    },
  });
}

